        prerequisites = set()

        for exploit in exploits:
            notes = exploit.get('notes', '')
            # Parse notes for prerequisites
            if 'require' in notes.lower():
                lines = notes.split('\n')
                for line in lines:
                    if 'require' in line.lower():
                        prerequisites.add(line.strip())

        return list(prerequisites) if prerequisites else [
